window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"ZMF-H87mefc","speaker":"Andrej Plenković","role":"Prime Minister","country":"Croatia","region":"Europe","url":"https://www.youtube.com/watch?v=ZMF-H87mefc","date":"20260923","title":"🇭🇷 Croatia - Prime Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1015,"words":1964,"counts":{"claims":29,"promises":6,"attacks":1},"topics":[{"topic":"Bosnia Herzegovina","share":0.1236,"seconds":125},{"topic":"Illegal migration","share":0.074,"seconds":75},{"topic":"AI regulation","share":0.0704,"seconds":71},{"topic":"Croatia UN experience","share":0.0686,"seconds":70},{"topic":"Russia-Ukraine war","share":0.0678,"seconds":69},{"topic":"Croatia experience","share":0.0675,"seconds":69},{"topic":"Croatia aid","share":0.0664,"seconds":67},{"topic":"Israel-Gaza","share":0.0658,"seconds":67},{"topic":"Rule-based multilateralism","share":0.0656,"seconds":67},{"topic":"Maritime security","share":0.0644,"seconds":65},{"topic":"UN reform","share":0.0643,"seconds":65},{"topic":"Croatia defense","share":0.0618,"seconds":63},{"topic":"Croatia electoral reform","share":0.0612,"seconds":62},{"topic":"Sustainable goals","share":0.0599,"seconds":61},{"topic":"Ceremony","share":0.0186,"seconds":19}],"timeline":[[0,69,"Croatia experience"],[70,136,"Rule-based multilateralism"],[138,206,"Russia-Ukraine war"],[207,274,"Israel-Gaza"],[276,341,"Maritime security"],[342,407,"UN reform"],[409,480,"AI regulation"],[482,557,"Illegal migration"],[558,621,"Bosnia Herzegovina"],[622,685,"Bosnia Herzegovina"],[686,748,"Croatia electoral reform"],[750,812,"Croatia defense"],[814,881,"Croatia aid"],[883,943,"Sustainable goals"],[946,1016,"Croatia UN experience"],[1017,1036,"Ceremony"]],"stances":{"Croatia experience":"Andrej Plenković states that Croatia has a unique experience to share based on its history of enduring aggression, defending freedom, and rebuilding.","Rule-based multilateralism":"Andrej Plenković states that Croatia supports rule-based multilateralism as the pinnacle of human cooperation because it provides order and protects sovereign equality for smaller states.","Russia-Ukraine war":"Andrej Plenković states that Russia's war is a direct assault on international rules and affirms Croatia's continued support for Ukraine's sovereignty and territorial integrity.","Israel-Gaza":"Andrej Plenković states that protection of civilians, humanitarian access, and a two-state solution are essential to ending violence in the region.","Maritime security":"Andrej Plenković states that freedom of navigation and maritime security are both a national interest and a global responsibility, emphasizing the need for strict implementation of the United Nations Convention on the Law of the Sea.","UN reform":"Andrej Plenković advocates for a more effective, accountable, and financially sustainable United Nations with a representative Security Council and emphasizes the need for strong leadership to implement measurable reforms.","AI regulation":"Andrej Plenković states that artificial intelligence development must align with legal frameworks, human dignity, and democratic accountability.","Illegal migration":"Andrej Plenković states that uncontrolled migration is unacceptable, emphasizes the need to uphold the rule of law, and affirms Croatia's determination to fight criminal networks while fulfilling its responsibility as an EU external border country.","Bosnia Herzegovina":"Andrej Plenković asserts that Ratko Mladić was a convicted war criminal responsible for the Srebrenica genocide and other war crimes, and that honoring him in Serbia is an affront to victims and international courts.","Croatia electoral reform":"Andrej Plenković argues that the electoral reform is essential for restoring legitimate political representation and opposing forces that jeopardize equality.","Croatia defense":"Andrej Plenković states that Croatia has tripled its defense budget and is implementing domestic reforms to increase resilience and capacity for international missions.","Croatia aid":"Andrej Plenković states that Croatia is increasing its official and humanitarian development assistance despite global reductions and outlines specific areas of support.","Sustainable goals":"Andrej Plenković states that Croatia ranks among the top 15 countries in implementing sustainable development goals and argues that credibility is essential for rebuilding trust in multilateralism.","Croatia UN experience":"Andrej Plenković argues that Croatia's difficult historical journey from war to EU membership provides a unique perspective on international cooperation and the necessity of the United Nations.","Ceremony":"Andrej Plenković concludes his address by expressing a desire for commitments to reach the intended beneficiaries and thanks the assembly."},"claims":[{"t":52,"quote":"Croatia brings the experience of a nation that within one generation endured aggression and occupation, defended its freedom, and rebuilt","topic":"Croatia experience","kind":"fact"},{"t":62,"quote":"It joined UN, NATO, and the EU, and developed a flourishing democracy and a growing economy.","topic":"Croatia experience","kind":"fact"},{"t":76,"quote":"Over the past decade as Prime Minister, I have seen Croatia translate those experiences into progress at home and more responsibility abroad.","topic":"Rule-based multilateralism","kind":"self_credit"},{"t":124,"quote":"For smaller and medium-sized states, international law is not an abstraction. It is the line between order and between sovereign equality and the rule of force.","topic":"Rule-based multilateralism","kind":"fact"},{"t":142,"quote":"brutal aggression and occupation of more than one quarter of our territory in the '90s, in the war which claimed nearly 20,000 lives","topic":"Russia-Ukraine war","kind":"fact"},{"t":152,"quote":"more than three decades later, Croatia continues to search for 1,725 missing persons","topic":"Russia-Ukraine war","kind":"number"},{"t":220,"quote":"Croatia supports a negotiated two-state solution in which Israelis and Palestinians will live in peace","topic":"Israel-Gaza","kind":"fact"},{"t":246,"quote":"War disrupts food and energy supplies, while insecurity from the Strait of Hormuz to the Black Sea affects shipping, prices, and livelihoods across continents","topic":"Israel-Gaza","kind":"fact"},{"t":278,"quote":"these shocks are real as they ripple into domestic inflationary pressures affecting everything from wages and pensions to food prices and basic","topic":"Maritime security","kind":"fact"},{"t":301,"quote":"For us, freedom of navigation and maritime security are both a national interest and a global responsibility.","topic":"Maritime security","kind":"fact"},{"t":346,"quote":"Croatia supports a UN that is more effective, accountable, and financially sustainable, and stronger across all three pillars: peace and security, sustainable development, and of course, human rights.","topic":"UN reform","kind":"fact"},{"t":368,"quote":"When the Council is blocked, the General Assembly can and must act, but it cannot replace the Council's primary responsibility under the Charter.","topic":"UN reform","kind":"fact"},{"t":409,"quote":"Artificial intelligence can accelerate development, but its use must remain consistent with legal frameworks, human dignity, and democratic accountability.","topic":"AI regulation","kind":"fact"},{"t":454,"quote":"For Europe, which imports most of the energy it consumes, the case for producing more renewable energy at home now reaches far beyond climate policy.","topic":"AI regulation","kind":"fact"},{"t":482,"quote":"The same principle applies to illegal which has caused mistrust in Europe and altered the political landscape in many This situation is unacceptable, and it cannot continue.","topic":"Illegal migration","kind":"fact"},{"t":516,"quote":"As an EU external border country, Croatia carries an additional responsibility, and we will fulfill it with determination.","topic":"Illegal migration","kind":"self_credit"},{"t":581,"quote":"Ratko Mladić was a convicted war criminal responsible for the Srebrenica genocide, the first genocide in Europe since the Holocaust.","topic":"Bosnia Herzegovina","kind":"fact"},{"t":597,"quote":"his trail of war crimes stretches further back to the shelling of Croatian cities, the murder of civilians, the mining of dams, and the destruction of cultural heritage and industrial facilities.","topic":"Bosnia Herzegovina","kind":"fact"},{"t":622,"quote":"The participation of state representatives and the public acclaim that accompanied the ceremonies totally incompatible with the values of a union Serbia seeks to join.","topic":"Bosnia Herzegovina","kind":"fact"},{"t":650,"quote":"The Dayton Peace Accords ended the war and established the constitutional framework for Bosnia and Herzegovina, one state, two entities, and three constituent peoples, Croats, Bosniaks, and Serbs.","topic":"Bosnia Herzegovina","kind":"fact"},{"t":668,"quote":"Yet the Croats of Bosnia and Herzegovina are still being denied legitimate including in the presidency of the That is unjust, destabilizing, and contrary to the spirit of Dayton.","topic":"Bosnia Herzegovina","kind":"fact"},{"t":731,"quote":"Over the past decade, Croatia has doubled the size of its economy in nominal terms while reducing its public debt-to-GDP ratio by 30 percentage points from its pandemic peak.","topic":"Croatia electoral reform","kind":"number"},{"t":744,"quote":"Six consecutive sovereign credit rating upgrades have brought us into the A category.","topic":"Croatia electoral reform","kind":"fact"},{"t":750,"quote":"We have tripled our defense budget with approximately 1/3 of that spending allocated to military","topic":"Croatia defense","kind":"number"},{"t":814,"quote":"Last year alone, the world's official development assistance was reduced by almost 25%.","topic":"Croatia aid","kind":"number"},{"t":833,"quote":"Between 2016 and 24, our official development assistance increased fivefold, while our humanitarian assistance grew more than 21-fold.","topic":"Croatia aid","kind":"number"},{"t":892,"quote":"Croatia persistently ranks among the world's 15 highest-performing countries in implementing the sustainable development goals.","topic":"Sustainable goals","kind":"number"},{"t":947,"quote":"Croatia's modern journey began in war, but war did not define its","topic":"Croatia UN experience","kind":"fact"},{"t":966,"quote":"Reform gave us a bridge from vulnerability to resilience and from post-war recovery to membership in the EU, the Eurozone, and","topic":"Croatia UN experience","kind":"fact"}],"promises":[{"t":183,"quote":"Croatia will continue to support Ukraine's sovereignty, independence, and territorial integrity","topic":"Russia-Ukraine war","kind":"promise"},{"t":262,"quote":"we are dealing with the consequences of energy price pressures by passing decrees to protect Croatian citizens and economy from energy shocks created far away from our shores","topic":"Israel-Gaza","kind":"promise"},{"t":509,"quote":"We are not allowing uncontrolled migration, and we are fighting the criminal networks that facilitate it.","topic":"Illegal migration","kind":"promise"},{"t":516,"quote":"As an EU external border country, Croatia carries an additional responsibility, and we will fulfill it with determination.","topic":"Illegal migration","kind":"promise"},{"t":536,"quote":"Croatia will continue to support a merit-based EU enlargement.","topic":"Illegal migration","kind":"promise"},{"t":873,"quote":"If elected to the presidency of ECOSOC for the 27-28 cycle, Croatia will work to strengthen coordination and accountability.","topic":"Croatia aid","kind":"promise"}],"attacks":[{"t":612,"quote":"The military and official honors accorded to Mladić in Serbia were an affront to his victims and to the judgments of international courts.","topic":"Bosnia Herzegovina","target":"Serbia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":"Croatia experience","text":"The assembly will hear an address by his Excellency Andre Plenkovic, Prime Minister of the Republic of I request protocol to escort his Excellency and invite him to address the &gt;&gt; Good evening, Madam Excellencies, ladies and gentlemen. We come to this assembly from countries that differ in size, population, and Yet here, precisely because of that, every country has its unique experience to share, responsibilities to assume, and a contribution to make. Croatia brings the experience of a nation that within one generation endured aggression and occupation, defended its freedom, and rebuilt It joined UN, NATO, and the EU, and developed a flourishing democracy and a growing economy."},{"t":70,"topic":"Rule-based multilateralism","text":"Our path and our transition were neither straight nor easy, but we made it. Over the past decade as Prime Minister, I have seen Croatia translate those experiences into progress at home and more responsibility abroad. They have reinforced three convictions that speak directly to the theme of this First, rules are our common compass. Second, transformation help us build resilience. Third, trust is earned only through Ladies and gentlemen, we support rule-based multilateralism as is pinnacle of human cooperation, not because we are naive, but because we have seen and experienced the For smaller and medium-sized states, international law is not an abstraction. It is the line between order and between sovereign equality and the rule of force."},{"t":138,"topic":"Russia-Ukraine war","text":"The rule of force, such as witnessed by Croatia during the brutal aggression and occupation of more than one quarter of our territory in the '90s, in the war which claimed nearly 20,000 lives, and after which, more than three decades later, Croatia continues to search for 1,725 missing persons. A poignant example that the consequences of war do not end when the weapons fall silent. peace requires courage, credible institutions, and rules that apply equally to everyone. Russia's ongoing war of aggression against Ukraine is a direct assault on those rules. Croatia will continue to support Ukraine's sovereignty, independence, and territorial integrity, and a comprehensive, just, and lasting peace based on the UN Charter. Peace cannot reward conquest, and recovery cannot be separated from The same compass must guide us in the Middle East."},{"t":207,"topic":"Israel-Gaza","text":"Protection of civilians, unhindered humanitarian access, respect for international law, and a credible political horizon are essential to breaking the cycle of violence. Croatia supports a negotiated two-state solution in which Israelis and Palestinians will live in peace and From Sudan and Myanmar to the Sahel and the Great Lakes region, civilians bear the highest cost when rules are ignored and diplomacy fails. And no crisis remains local for long. War disrupts food and energy supplies, while insecurity from the Strait of Hormuz to the Black Sea affects shipping, prices, and livelihoods across continents. This is why as a government, we are dealing with the consequences of energy price pressures by passing decrees to protect Croatian citizens and economy from energy shocks created far away from our shores."},{"t":276,"topic":"Maritime security","text":"As distant as they may seem, these shocks are real as they ripple into domestic inflationary pressures affecting everything from wages and pensions to food prices and basic This is why freedom of navigation, maritime security, and the strict implementation of the United Nations Convention on the Law of the Sea matter to everyone. For us, freedom of navigation and maritime security are both a national interest and a global responsibility. Common rules do not hold us back. They provide the stability and predictability necessary for countries to advance their ambitions. The world is being transformed by climate change, demographic pressures, illegal migration, and geopolitical Our responsibility is to govern them so that change expands human freedom and security instead of weakening them."},{"t":342,"topic":"UN reform","text":"The United Nations must begin with its own transformation. Croatia supports a UN that is more effective, accountable, and financially sustainable, and stronger across all three pillars: peace and security, sustainable development, and of course, human rights. Reform must also produce a more representative and effective Security When the Council is blocked, the General Assembly can and must act, but it cannot replace the Council's primary responsibility under the Charter. This makes the selection of the next Secretary-General all the more relevant. I thank, therefore, Secretary-General Guterres for his work over the last The United Nations needs leadership capable of bringing member states together, defending the Charter, and turning reform into measurable results. No country alone can successfully respond to the global transformations we witness today."},{"t":409,"topic":"AI regulation","text":"Artificial intelligence can accelerate development, but its use must remain consistent with legal frameworks, human dignity, and democratic accountability. Renewed nuclear rhetoric makes a firm commitment to the Treaty on the Non-Proliferation of Nuclear Weapons more important than ever. Climate action should be used to strengthen energy security and social Our experience shows that the green transition should not be ideological. It can endure only when it is technologically realistic, socially fair, compatible with secure and affordable energy, and supportive of overall development. For Europe, which imports most of the energy it consumes, the case for producing more renewable energy at home now reaches far beyond climate policy. It is a strategic necessity. It strengthens Europe's sovereignty and capacity to act, reduces external dependence, creates economic opportunity, and makes our societies more resilient."},{"t":482,"topic":"Illegal migration","text":"The same principle applies to illegal which has caused mistrust in Europe and altered the political landscape in many This situation is unacceptable, and it cannot continue. The rule of law must be upheld, and legal procedures must be followed. Our primary responsibility is to our citizens, and it starts at our borders. We are not allowing uncontrolled migration, and we are fighting the criminal networks that facilitate it. As an EU external border country, Croatia carries an additional responsibility, and we will fulfill it with determination. Transformation is equally important in our own neighborhood. Southeast Europe remains the unfinished part of the European project. Croatia will continue to support a merit-based EU enlargement. EU membership can turn borders of division into lines of cooperation, and reforms on paper into stronger institutions and better living But European transformation requires honesty about the past."},{"t":558,"topic":"Bosnia Herzegovina","text":"Reconciliation becomes possible when responsibility for the crimes of the past is acknowledged and their glorification rejected. That standard allows no national That means respect for victims and clear rejection of historical revisionism, not the glorification of war criminals. Ratko Mladić was a convicted war criminal responsible for the Srebrenica genocide, the first genocide in Europe since the Holocaust. While his criminal record reached its nefarious culmination in Srebrenica, his trail of war crimes stretches further back to the shelling of Croatian cities, the murder of civilians, the mining of dams, and the destruction of cultural heritage and industrial facilities. The military and official honors accorded to Mladić in Serbia were an affront to his victims and to the judgments of international courts."},{"t":622,"topic":"Bosnia Herzegovina","text":"The participation of state representatives and the public acclaim that accompanied the ceremonies totally incompatible with the values of a union Serbia seeks to join. The same commitment to equality and reform should guide Bosnia and As a signatory to the Dayton Peace Accords and a neighbor and a friend of Bosnia and Herzegovina, Croatia is one of the strongest advocates of its European future. The Dayton Peace Accords ended the war and established the constitutional framework for Bosnia and Herzegovina, one state, two entities, and three constituent peoples, Croats, Bosniaks, and Serbs. That balance is the foundation on which peace was built. Yet the Croats of Bosnia and Herzegovina are still being denied legitimate including in the presidency of the That is unjust, destabilizing, and contrary to the spirit of Dayton. The solution is neither division nor domination."},{"t":686,"topic":"Croatia electoral reform","text":"It is carefully designed electoral reform that protects every citizen while ensuring that a basic principle of legitimate political representation of the constituent peoples is restored. Croatia will not tire of explaining why this reform is crucial for the entire country to reach its full potential. And we will not tire of opposing those political forces whose short-sighted pursuit of political gains jeopardizes equality of constituent peoples and the long-term Our own history confirms that transformation succeeds when it is rooted in inclusion, responsibility, and Over the past decade, Croatia has doubled the size of its economy in nominal terms while reducing its public debt-to-GDP ratio by 30 percentage points from its pandemic peak. Six consecutive sovereign credit rating upgrades have brought us into the A category."},{"t":750,"topic":"Croatia defense","text":"We have tripled our defense budget with approximately 1/3 of that spending allocated to military In a changed security environment, we are strengthening our security and ensuring we are better equipped to support international stabilization missions abroad. Reforms we are pursuing domestically are increasing our overall resilience and giving us increased capacity to engage in a world which is rapidly changing. Ladies and gentlemen, the international system stutters when the distance between declaration and delivery becomes too wide. Trust returns when cooperation produces real, measurable results. It returns when a child is in school, a community is protected from violence, a mine that is removed from a field, or food reaches family. And it returns when institutions prevent conflict before it even begins."},{"t":814,"topic":"Croatia aid","text":"Last year alone, the world's official development assistance was reduced by almost 25%. This drop is the largest annual contraction on record for international Refusing to spiral into negative trends, Croatia is contributing more, not less. Between 2016 and 24, our official development assistance increased fivefold, while our humanitarian assistance grew more than 21-fold. With our UN partners, we are translating our commitment and funds into action. We support girls' education in Kenya, provide humanitarian assistance in Gaza, and assist Syrian refugee children. We also advance mine action in Ukraine, drawing on Croatia's own post-war experience, and protect women and girls from digital violence. This practical, inclusive, and human-centered approach is also what Croatia brings to ECOSOC. If elected to the presidency of ECOSOC for the 27-28 cycle, Croatia will work to strengthen coordination and accountability."},{"t":883,"topic":"Sustainable goals","text":"As 2030 approaches, accelerating implementation of the sustainable goals continues to be a central priority. Croatia persistently ranks among the world's 15 highest-performing countries in implementing the sustainable development goals. Our experience is not a universal prescription, but evidence that national reform and international responsibility can and do advance It is this credibility that is in the foundation of trust in multilateralism that we wish to see rebuilt. Credibility which is strongest when every country, regardless of its size, wealth, or power, has a meaningful voice. The answer is therefore not less multilateralism that delivers. It is multilateralism that must deliver. It is this approach that Croatia would bring to the Security Council if elected to serve in 2030-31."},{"t":946,"topic":"Croatia UN experience","text":"Excellencies, Croatia's modern journey began in war, but war did not define its Our experience has shaped the way we understand international cooperation and the responsibilities that come with it. Rules gave us a compass when force sought to erase our borders. Reform gave us a bridge from vulnerability to resilience and from post-war recovery to membership in the EU, the Eurozone, and Delivery turned those ambitions into institutions, security, and better lives for our citizens, and gave us the capacity to contribute beyond our borders. That is the experience Croatia brings to the United Nations. Not a claim to perfection, but the perspective of a country that has traveled a difficult road and learned from it. The United Nations remains indispensable because no country can navigate today's storms alone. Let us therefore rebuild trust by defending our common compass and managing change so that it strengthens human dignity."},{"t":1017,"topic":"Ceremony","text":"Let us ensure that our commitment reach the people for whom they were made. Thank you. &gt;&gt; On behalf of the Assembly, I wish to thank the Prime Minister of the Republic of Croatia."}],"compare":[{"topic":"Bosnia and Herzegovina","share":0.126,"mean":0.0008,"rank":2,"others":1},{"topic":"Migration","share":0.0754,"mean":0.0045,"rank":6,"others":12},{"topic":"Artificial Intelligence","share":0.0718,"mean":0.0504,"rank":57,"others":83},{"topic":"Russia-Ukraine War","share":0.0691,"mean":0.0351,"rank":36,"others":44},{"topic":"Israel–Palestine","share":0.0671,"mean":0.0523,"rank":57,"others":76},{"topic":"International Law & Order","share":0.0669,"mean":0.0604,"rank":69,"others":102},{"topic":"Maritime Security","share":0.0656,"mean":0.0044,"rank":7,"others":9},{"topic":"UN & its reform","share":0.0655,"mean":0.2055,"rank":162,"others":170}]};
